mapper.select:
SELECT id AS "id", client_name AS "clientName", name AS "name", spec AS "spec", note AS "note",
       category AS "category", sale_type AS "saleType", remark AS "remark"
FROM recipe_drafts WHERE id = #{id}

mapper.update:
UPDATE recipe_drafts
   SET name = #{name}, spec = #{spec, jdbcType=VARCHAR}, note = #{note, jdbcType=VARCHAR}, category = #{category, jdbcType=VARCHAR},
       sale_type = #{saleType, jdbcType=VARCHAR}, remark = #{remark, jdbcType=VARCHAR}, updated_at = #{now}
 WHERE id = #{id}
